# SPDX-License-Identifier: Apache-2.0
#
# Linker version script for libv8malloc.so. A single SONAME-aligned
# version node holds every exported symbol; new symbols are added to
# the same node within a major release. A new node (V8MALLOC_2.0, etc.)
# is introduced only on a major bump.

V8MALLOC_1.0 {
	global:
		v8m_version;
		v8m_version_major;
		v8m_version_minor;
		v8m_version_patch;

		v8m_malloc;
		v8m_free;
		v8m_calloc;
		v8m_realloc;
		v8m_reallocarray;
		v8m_malloc_usable_size;
		v8m_aligned_alloc;
		v8m_posix_memalign;
		v8m_memalign;
		v8m_valloc;
		v8m_pvalloc;

		malloc;
		free;
		calloc;
		realloc;
		reallocarray;
		malloc_usable_size;
		aligned_alloc;
		posix_memalign;
		memalign;
		valloc;
		pvalloc;
	local:
		*;
};
